python3 -c "
def v2(n):
  c=0
  while n%2==0:
    n//=2;c+=1
  return c,n
def vp(n,p):
  c=0
  while n%p==0:
    n//=p;c+=1
  return c,n
def isprime(n):
  if n<2: return False
  if n%2==0: return n==2
  i=3
  while i*i<=n:
    if n%i==0: return False
    i+=2
  return True
sols=[]
for p in range(2,500):
  if not isprime(p): continue
  for c in range(1,300):
    v=(p+2)**c+1
    a,r=v2(v)
    b,rr=vp(r,p)
    if rr==1 and a>0 and b>0:
      sols.append((p,a,b,c))
print(sols)
